import subprocess, json
U = {"sa":"e0","owner":"e1","gm":"e2","staff":"e3","dokter":"e4","kasir":"e5","owner2":"e6"}
B1="00000000-0000-0000-0000-0000000000b1"; B2="00000000-0000-0000-0000-0000000000b2"; B3="00000000-0000-0000-0000-0000000000b3"
T1="00000000-0000-0000-0000-000000000001"; T2="00000000-0000-0000-0000-000000000002"
def uid(w): return f"00000000-0000-0000-0000-0000000000{U[w]}"
def q(who, sql):
    cmd = f"begin; set local role authenticated; select set_config('request.jwt.claim.sub','{uid(who)}',true) \\g /dev/null\n{sql};\ncommit;"
    r = subprocess.run(["psql","-h","/var/tmp/pgh","-p","5499","-U","postgres","-d","h","-tA","-v","ON_ERROR_STOP=1"], input=cmd, capture_output=True, text=True)
    out = [l for l in r.stdout.strip().splitlines() if l not in ("BEGIN","COMMIT","SET")]
    return (r.stderr.strip().split("\n")[0].replace("psql:<stdin>:","") if r.returncode else (out[-1] if out else ""))
def su(sql): return subprocess.run(["psql","-h","/var/tmp/pgh","-p","5499","-U","postgres","-d","h","-tA","-c",sql],capture_output=True,text=True).stdout.strip()
fails = 0
def chk(label, got, want=None, err=None):
    """want: substring harus ada; err: harus galat berisi substring."""
    global fails
    ok = (err is not None and got.startswith("ERROR") or err is not None and "ERROR" in got) and (err in got) if err is not None else (want in got if want is not None else True)
    if not ok: fails += 1
    print(("  ok  " if ok else " GAGAL ") + f"{label:62} {got}"[:200])
def sec(t): print("── "+t)

